import random
def write_amp(op, blocks=256, ppb=64, writes=300000, seed=1):
    random.seed(seed)
    logical = int(blocks * ppb * (1 - op))
    valid = [set() for _ in range(blocks)]
    where = {}
    free = list(range(1, blocks)); state = {"cur": 0, "fill": 0, "flash": 0}
    def put(lpn):
        if state["fill"] == ppb:
            state["cur"] = free.pop(); state["fill"] = 0
        valid[state["cur"]].add(lpn); where[lpn] = state["cur"]
        state["fill"] += 1; state["flash"] += 1
    for lpn in range(logical): put(lpn)
    base = state["flash"]
    for _ in range(writes):
        lpn = random.randrange(logical)
        valid[where[lpn]].discard(lpn); put(lpn)
        while len(free) < 2:                    # greedy GC: block with fewest valid pages
            used = [b for b in range(blocks) if b != state["cur"] and b not in free]
            v = min(used, key=lambda b: len(valid[b]))
            moved = list(valid[v]); valid[v].clear(); free.insert(0, v)
            for m in moved: put(m)
    return (state["flash"] - base) / writes
for op in (0.07, 0.15, 0.28):
    print(f"over-provision {op:.0%} -> WAF {write_amp(op):.2f}")
# over-provision 7% -> WAF 7.30
# over-provision 15% -> WAF 3.49
# over-provision 28% -> WAF 1.97

import random
from collections import OrderedDict
random.seed(7)
N, SLOTS = 20000, 1024
w = [1/(i+1)**0.9 for i in range(N)]
trace = random.choices(range(N), weights=w, k=100000)
trace += [random.randrange(N) for _ in range(30000)]   # one-time scan
trace += random.choices(range(N), weights=w, k=100000)

def lru(tr):
    c, hit = OrderedDict(), 0
    for p in tr:
        if p in c: hit += 1; c.move_to_end(p)
        else:
            c[p] = 1
            if len(c) > SLOTS: c.popitem(last=False)
    return hit/len(tr)

def two_q(tr, probation=256):
    a1, am, hit = OrderedDict(), OrderedDict(), 0
    for p in tr:
        if p in am: hit += 1; am.move_to_end(p)
        elif p in a1:
            hit += 1; del a1[p]; am[p] = 1
            if len(am) > SLOTS - probation: am.popitem(last=False)
        else:
            a1[p] = 1
            if len(a1) > probation: a1.popitem(last=False)
    return hit/len(tr)

print(f"LRU hit {lru(trace):.3f}")
print(f"2Q  hit {two_q(trace):.3f}")
# LRU hit 0.422
# 2Q  hit 0.481
